from __future__ import annotations

import json
from pathlib import Path

from .authorization import SOURCE
from .utils import HERE, ROOT, START_SHA, git_blob_sha256, now_stamps, read_json, sha256_json, write_json

RAW=HERE/"raw/failure_ledger.json"; DIAG=HERE/"diagnostics/failure_ledger.json"; CENTRAL=ROOT/"docs/V837_FAILURE_LEDGER.md"
REQUIRED=("failure_id","version","stage","timestamp_utc","source_commit","source_artifact_hashes","scientific_question","hypothesis","why_it_was_tested","exact_implementation","data_used","fit_seeds","selection_seeds","controls","parameter_count","mac_cost","metrics","acceptance_gate","failed_conditions","distance_from_gate","result_status","failure_type","confounds_ruled_out","confounds_remaining","scientific_interpretation","do_not_repeat_unchanged","uncertainty_remaining","next_justified_experiment","reproduction_command","artifact_paths")


def _base()->dict: return {"version":"V837am","append_only":True,"entries":[]}
def load()->dict: return read_json(RAW) if RAW.is_file() else _base()

def _sync(payload): write_json(RAW,payload);write_json(DIAG,payload)

def add(entry:dict,append_central:bool=True):
    p=load(); missing=[k for k in REQUIRED if k not in entry]
    if missing: raise RuntimeError(f"FAILURE_LEDGER_ENTRY_INCOMPLETE:{missing}")
    if any(e["failure_id"]==entry["failure_id"] for e in p["entries"]): return
    p["entries"].append(entry);_sync(p)
    if append_central:
        with CENTRAL.open("a",encoding="utf-8",newline="\n") as f:
            f.write(f"## {entry['failure_id']} — {entry['version']} / {entry['stage']}\n\n")
            f.write(f"- **Hypothesis:** {entry['hypothesis']}\n- **Result:** {entry['result_status']} / {entry['failure_type']}\n- **Failed gate:** {', '.join(entry['failed_conditions'])}\n- **Meaning:** {entry['scientific_interpretation']}\n- **Do not repeat unchanged:** {entry['do_not_repeat_unchanged']}\n- **Source commit:** `{entry['source_commit']}`\n- **Artifacts:** {', '.join(entry['artifact_paths'])}\n\n")

def make_entry(*,failure_id,version,stage,hypothesis,why,implementation,data,fit_seeds,selection_seeds,controls,params,macs,metrics,gate,failed,distance,status,failure_type,ruled,remaining,meaning,uncertainty,next_action,reproduce,artifacts,source_hashes=None):
    u,l=now_stamps();return {"failure_id":failure_id,"version":version,"stage":stage,"timestamp_utc":u,"timestamp_local":l,"source_commit":START_SHA,"source_artifact_hashes":source_hashes or {},"scientific_question":"Why can the causally important recurring V837ak computation not be reused across independently trained organisms?","hypothesis":hypothesis,"why_it_was_tested":why,"exact_implementation":implementation,"data_used":data,"fit_seeds":fit_seeds,"selection_seeds":selection_seeds,"controls":controls,"parameter_count":params,"mac_cost":macs,"metrics":metrics,"acceptance_gate":gate,"failed_conditions":failed,"distance_from_gate":distance,"result_status":status,"failure_type":failure_type,"confounds_ruled_out":ruled,"confounds_remaining":remaining,"scientific_interpretation":meaning,"do_not_repeat_unchanged":True,"uncertainty_remaining":uncertainty,"next_justified_experiment":next_action,"reproduction_command":reproduce,"artifact_paths":artifacts}

